#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
using namespace std;

const int MAXN=12, INF=1000000;
int dx[4]={-1,1,0,0}, dy[4]={0,0,-1,1};
int N,T;
char grid1[MAXN][MAXN], grid2[MAXN][MAXN];
int A[MAXN][MAXN];
int B[MAXN][MAXN][MAXN][MAXN];

struct Edge {
    int a, b, cap, flow;
};

int nodeCount, source, sink;
int dist[MAX_NETWORK_NODES], ptr[MAX_NETWORK_NODES], queue[MAX_NETWORK_NODES];
vector<Edge> edges;
vector<int> graph[MAX_NETWORK_NODES];

void addEdge(int a, int b, int cap) {
    Edge e1={a,b,cap,0}, e2={b,a,0,0};
    graph[a].push_back((int)edges.size()); edges.push_back(e1);
    graph[b].push_back((int)edges.size()); edges.push_back(e2);
}

bool bfs() {
    int front=0, back=0;
    queue[back++]=source;
    memset(dist,-1,sizeof(dist));
    dist[source]=0;
    while(front<back && dist[sink]==-1){
        int v=queue[front++];
        for(auto id:graph[v]){
            int to=edges[id].b;
            if(dist[to]==-1 && edges[id].flow<edges[id].cap){
                queue[back++]=to;
                dist[to]=dist[v]+1;
            }
        }
    }
    return dist[sink]!=-1;
}

int sendFlow(int v, int flow) {
    if(v==sink) return flow;
    for(int &i=ptr[v];i<(int)graph[v].size();i++){
        int id=graph[v][i], to=edges[id].b;
        if(dist[to]==dist[v]+1 && edges[id].flow<edges[id].cap){
            int pushed=min(flow,edges[id].cap-edges[id].flow);
            int pushedFlow=sendFlow(to,pushed);
            if(pushedFlow>0){
                edges[id].flow+=pushedFlow;
                edges[id^1].flow-=pushedFlow;
                return pushedFlow;
            }
        }
    }
    return 0;
}

int maxFlow() {
    int total=0;
    while(bfs()){
        memset(ptr,0,sizeof(ptr));
        while(int pushed=sendFlow(source,INF))
            total+=pushed;
    }
    return total;
}

int getID(int x,int y){ return x*N+y; }

void setupNetwork() {
    source=0; sink=2*N*N+1;
    nodeCount=2*N*N+2;
    for(int i=0;i<N;i++)
        for(int j=0;j<N;j++){
            if(grid1[i][j]>'0' && grid1[i][j]<='9')
                addEdge(source,1+getID(i,j),grid1[i][j]-'0');
            if(grid2[i][j]>'0' && grid2[i][j]<='9')
                addEdge(N*N+1+getID(i,j),sink,grid2[i][j]-'0');
        }
    for(int x1=0;x1<N;x1++)
        for(int y1=0;y1<N;y1++)
            for(int x2=0;x2<N;x2++)
                for(int y2=0;y2<N;y2++){
                    if(B[x1][y1][x2][y2]){
                        addEdge(1+getID(x1,y1),N*N+1+getID(x2,y2),INF);
                    }
                }
}

int main() {
    cin>>N>>T;
    for(int i=0;i<N;i++) cin>>grid1[i];
    for(int i=0;i<N;i++) cin>>grid2[i];
    for(int i=0;i<N;i++)
        for(int j=0;j<N;j++) A[i][j]=INF;
    queue<pair<int,int>> Q;
    for(int x=0;x<N;x++)
        for(int y=0;y<N;y++)
            if(grid1[x][y]=='Z'){
                for(int i=0;i<4;i++){
                    int nx=x+dx[i], ny=y+dy[i];
                    if(nx>=0 && nx<N && ny>=0 && ny<N && grid1[nx][ny]!='Y'){
                        A[nx][ny]=1;
                        Q.push({nx,ny});
                    }
                }
            }
    while(!Q.empty()){
        auto p=Q.front(); Q.pop();
        int x=p.first, y=p.second;
        for(int i=0;i<4;i++){
            int nx=x+dx[i], ny=y+dy[i];
            if(nx>=0 && nx<N && ny>=0 && ny<N && grid1[nx][ny]!='Y' && grid1[nx][ny]!='Z' && A[nx][ny]==INF){
                A[nx][ny]=A[x][y]+1;
                Q.push({nx,ny});
            }
        }
    }
    for(int x1=0;x1<N;x1++)
        for(int y1=0;y1<N;y1++)
            for(int x2=0;x2<N;x2++)
                for(int y2=0;y2<N;y2++){
                    if(grid1[x1][y1]=='Y'||grid1[x1][y1]=='Z'||grid1[x2][y2]=='Y'||grid1[x2][y2]=='Z'){
                        B[x1][y1][x2][y2]=0; continue;
                    }
                    for(int i=0;i<N;i++)
                        for(int j=0;j<N;j++) A[i][j]=INF;
                    queue<pair<int,int>> Q2;
                    A[x1][y1]=0; Q2.push({x1,y1});
                    int c=0;
                    while(!Q2.empty()){
                        auto p2=Q2.front(); Q2.pop();
                        int x=p2.first, y=p2.second;
                        if(x==x2 && y==y2){ c=1; break; }
                        if(A[x][y]>=T || A[x][y]>=A[x][y]) continue;
                        for(int i=0;i<4;i++){
                            int nx=x+dx[i], ny=y+dy[i];
                            if(nx>=0 && nx<N && ny>=0 && ny<N && grid1[nx][ny]!='Y' && grid1[nx][ny]!='Z' && A[nx][ny]==INF && A[x][y]+1<=A[nx][ny]){
                                A[nx][ny]=A[x][y]+1;
                                Q2.push({nx,ny});
                            }
                        }
                    }
                    B[x1][y1][x2][y2]=c;
                }
    setupNetwork();
    cout<<maxFlow()<<endl;
    return 0;
}
